// Validate retry request
const stepName = event.body?.failed_step;
const payload = event.body?.input_payload;

if (!stepName) throw new Error("Missing required field: failed_step");
if (!payload) throw new Error("Missing required field: input_payload");

return {
  failed_step: stepName,
  input_payload: payload
};

// Generic retry wrapper for any failing LLM step

async function wait(ms) { return new Promise(r => setTimeout(r, ms)); }

const MAX_RETRIES = 4;

async function attempt(fn) {
  let lastError;
  for (let i = 1; i <= MAX_RETRIES; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      console.log(`Retry attempt ${i} failed:`, err.message);
      await wait(500 * i * i); // exponential backoff
    }
  }
  throw new Error(`Step failed after ${MAX_RETRIES} retries: ${lastError.message}`);
}

return { attempt };

// Dynamically reruns the failed step using the provided payload.
// We call the same components used in main_workflow.json.

const step = steps.extract_retry_payload.failed_step;
const payload = steps.extract_retry_payload.input_payload;
const attempt = steps.retry_logic.attempt;

const COMPONENTS = {
  discovery: "matthewvannicola/premortem-ai/pipedream/components/discovery",
  scoring: "matthewvannicola/premortem-ai/pipedream/components/scoring",
  themes: "matthewvannicola/premortem-ai/pipedream/components/themes",
  mitigation: "matthewvannicola/premortem-ai/pipedream/components/mitigation",
  summary: "matthewvannicola/premortem-ai/pipedream/components/summary",
  final_report: "matthewvannicola/premortem-ai/pipedream/components/final_report"
};

if (!COMPONENTS[step]) {
  throw new Error(`Unknown pipeline step: ${step}`);
}

// Run step with retries
return await attempt(async () => {
  const component = require(COMPONENTS[step]);
  return await component.run({ props: payload });
});

// Return retry result with status
return {
  status: "retry_success",
  step: steps.extract_retry_payload.failed_step,
  output: steps.rerun_failed_step
};
